using AfriWallet.Merchants.Settlement.Api.Contracts;using AfriWallet.Merchants.Settlement.Application.Abstractions;using AfriWallet.Merchants.Settlement.Application.Commands;using AfriWallet.Merchants.Settlement.Application.Policies;using AfriWallet.Merchants.Settlement.Application.Services;using AfriWallet.Merchants.Settlement.Infrastructure;var b=WebApplication.CreateBuilder(args);b.Services.AddSingleton<ICaptureEligibleDecisionReader,SandboxCaptureEligibleDecisionReader>();b.Services.AddSingleton<IMerchantSettlementRepository,InMemoryMerchantSettlementRepository>();b.Services.AddSingleton<IMerchantSettlementProvider,SandboxMerchantSettlementProvider>();b.Services.AddSingleton<IMerchantSettlementAuditStore,InMemoryMerchantSettlementAuditStore>();b.Services.AddSingleton<IMerchantSettlementClock,SystemMerchantSettlementClock>();b.Services.AddSingleton<MerchantSettlementRoutingPolicy>();b.Services.AddSingleton<MerchantSettlementRetryPolicy>();b.Services.AddSingleton<MerchantSettlementService>();var app=b.Build();const string Actor="afriwallet-merchant-settlement-system";app.MapGet("/health",()=>Results.Ok(new{status="Healthy",delivery="AFW-DLV-0019.5",realCapturePerformed=false,realSettlementPerformed=false,realPayoutPerformed=false,merchantFundsMoved=false,walletBalanceMutated=false,directLedgerMutationPerformed=false}));app.MapPost("/api/v1/merchant-settlements",async(CreateMerchantSettlementRequest r,MerchantSettlementService s,CancellationToken ct)=>{var x=await s.CreateAsync(new CreateMerchantSettlementCommand(r.PaymentDecisionId,r.Route,r.IdempotencyKey,Actor),ct);return Results.Created($"/api/v1/merchant-settlements/{x.SettlementId}",x);});app.MapPost("/api/v1/merchant-settlements/{id:guid}/dispatch",async(Guid id,MerchantSettlementService s,CancellationToken ct)=>Results.Ok(await s.DispatchAsync(new DispatchMerchantSettlementCommand(id,Actor),ct)));app.MapPost("/api/v1/merchant-settlements/{id:guid}/retry",async(Guid id,MerchantSettlementService s,CancellationToken ct)=>Results.Ok(await s.RetryAsync(new RetryMerchantSettlementCommand(id,Actor),ct)));app.MapPost("/api/v1/merchant-settlements/{id:guid}/compensate",async(Guid id,MerchantSettlementService s,CancellationToken ct)=>Results.Ok(await s.CompensateAsync(new CompensateMerchantSettlementCommand(id,Actor),ct)));app.MapPost("/api/v1/merchant-settlements/{id:guid}/complete",async(Guid id,MerchantSettlementService s,CancellationToken ct)=>Results.Ok(await s.CompleteAsync(new CompleteMerchantSettlementCommand(id,Actor),ct)));app.MapGet("/api/v1/merchant-settlements/{id:guid}",async(Guid id,MerchantSettlementService s,CancellationToken ct)=>Results.Ok(await s.GetAsync(id,ct)));app.Run();
